import{_ as e,o as i,c as t,a2 as a}from"./chunks/framework.CdvW4CUT.js";const u=JSON.parse('{"title":"Proximity Voice Chat Setup","description":"","frontmatter":{},"headers":[],"relativePath":"guide/voice-chat.md","filePath":"guide/voice-chat.md"}'),n={name:"guide/voice-chat.md"};function r(l,o,s,d,c,h){return i(),t("div",null,[...o[0]||(o[0]=[a('<h1 id="proximity-voice-chat-setup" tabindex="-1">Proximity Voice Chat Setup <a class="header-anchor" href="#proximity-voice-chat-setup" aria-label="Permalink to &quot;Proximity Voice Chat Setup&quot;">​</a></h1><p>LlamaCraft supports high-performance 3D spatial directional proximity voice chat. Sound originates from player models in real-time with realistic distance roll-off, wall muffling, and environmental reverberation.</p><hr><h2 id="how-it-works" tabindex="-1">How It Works <a class="header-anchor" href="#how-it-works" aria-label="Permalink to &quot;How It Works&quot;">​</a></h2><p>Proximity voice uses a dedicated audio socket running alongside the game server. When players move, in-game coordinate packets update the audio engine to adjust volume and stereo panning.</p><ul><li><strong>Proximity Distance</strong>: Active within 24 blocks.</li><li><strong>Directional Panning</strong>: Left and right ear stereo balancing based on player orientation.</li><li><strong>Sneak Whisper</strong>: Decreases broadcast range to 4 blocks for private strategy.</li><li><strong>Sprint Shout</strong>: Expands broadcast range to 48 blocks across large battlefields.</li></ul><hr><h2 id="setup-by-platform" tabindex="-1">Setup by Platform <a class="header-anchor" href="#setup-by-platform" aria-label="Permalink to &quot;Setup by Platform&quot;">​</a></h2><h3 id="java-edition-modded-client" tabindex="-1">Java Edition (Modded Client) <a class="header-anchor" href="#java-edition-modded-client" aria-label="Permalink to &quot;Java Edition (Modded Client)&quot;">​</a></h3><p>If you play on Java, you can install the <strong>Simple Voice Chat</strong> client mod for the most seamless native experience:</p><ol><li>Ensure you have <strong>Fabric</strong> or <strong>Forge</strong> installed for Minecraft 1.21.</li><li>Download the matching <strong>Simple Voice Chat</strong> mod jar from Modrinth or CurseForge.</li><li>Place the <code>.jar</code> into your <code>.minecraft/mods</code> folder.</li><li>Join the server and press <code>V</code> to open your voice settings, test your microphone, and set Push-to-Talk or Voice Activation.</li></ol><hr><h3 id="bedrock-windows-pc-ios-android-consoles" tabindex="-1">Bedrock (Windows PC, iOS, Android, Consoles) <a class="header-anchor" href="#bedrock-windows-pc-ios-android-consoles" aria-label="Permalink to &quot;Bedrock (Windows PC, iOS, Android, Consoles)&quot;">​</a></h3><p>Bedrock players do <strong>not</strong> need to install any modified Minecraft clients.</p><h4 id="option-1-web-link-zero-downloads" tabindex="-1">Option 1: Web Link (Zero Downloads) <a class="header-anchor" href="#option-1-web-link-zero-downloads" aria-label="Permalink to &quot;Option 1: Web Link (Zero Downloads)&quot;">​</a></h4><ol><li>Join the server in Minecraft.</li><li>Type <code>/voice</code> or <code>/audio</code> in chat.</li><li>Click the secure link sent to you in chat.</li><li>Open the link in Chrome, Safari, or Edge on your phone or computer.</li><li>Allow microphone access when prompted. The web client automatically links to your player session.</li></ol><h4 id="option-2-bedrock-voice-chat-companion-app" tabindex="-1">Option 2: Bedrock Voice Chat Companion App <a class="header-anchor" href="#option-2-bedrock-voice-chat-companion-app" aria-label="Permalink to &quot;Option 2: Bedrock Voice Chat Companion App&quot;">​</a></h4><ol><li>Download the free companion app for Windows, iOS, or Android.</li><li>Open the app and enter the server IP: <code>164.152.106.210</code>.</li><li>The app authenticates your Gamertag and routes low-latency Opus audio in the background while you play.</li></ol><hr><h2 id="recommended-audio-settings" tabindex="-1">Recommended Audio Settings <a class="header-anchor" href="#recommended-audio-settings" aria-label="Permalink to &quot;Recommended Audio Settings&quot;">​</a></h2><ul><li><strong>Microphone Input</strong>: Select your headset microphone, not your built-in monitor mic.</li><li><strong>Activation Mode</strong>: Push-to-Talk or Voice Activity with noise suppression.</li><li><strong>Volume Normalization</strong>: Enable AGC (Automatic Gain Control) to keep party levels balanced.</li></ul>',21)])])}const m=e(n,[["render",r]]);export{u as __pageData,m as default};
